// Resolve an HH:MM "up by" time to the next time it occurs, as local ISO.
function nextOccurrenceISO(hhmm) {
  const [hh,mm] = hhmm.split(':').map(Number);
  const now = new Date();
  let t = new Date(now); t.setHours(hh, mm, 0, 0);
  if (t <= now) t.setDate(t.getDate()+1);
  const local = new Date(t.getTime() - t.getTimezoneOffset()*60000);
  return local.toISOString().slice(0,19);
}

