  $('#note').innerHTML =
    `You must be up by <b>${d.fitbit_set}</b> — set <i>that</i> as your Smart Wake alarm (it's the upper bound). `+
    `It fires within 30 min before, bracketing your cycle boundary at <b>${d.ideal_wake}</b>. `+
    `Pick a row and go to bed at the <b>Bed by</b> time to land that wake on a full cycle (asleep ~${$('#onset').value||15} min later). `+
    `Open the Fitbit app → Alarms → enable <b>Smart Wake</b> on ${d.fitbit_set}.`;
}

