const COUNTS = [3,4,5,6,7];
const OFFSET = 15;          // Smart Wake set-time offset past the cycle boundary
const TARGET_SLEEP = 480;   // 8 h — anchor for the highlighted default row
let mode = 'forward';

// Cycle count whose total sleep lands closest to the healthy target (ties → more).
function recommendedCycles(cycle){
  return COUNTS.reduce((best,n) =>
    Math.abs(n*cycle-TARGET_SLEEP) < Math.abs(best*cycle-TARGET_SLEEP) ? n : best, COUNTS[0]);
}

function readInputs(){
  const cycle = parseInt($('#cycle').value || DEFAULTS.cycle, 10);
  const onset = parseInt($('#onset').value || DEFAULTS.onset, 10);
  save('cycle', cycle); save('onset', onset);
  return { cycle, onset };
}

function recompute(){
  return mode === 'reverse' ? recomputeReverse() : recomputeForward();
}

function recomputeForward(){
  const { cycle, onset } = readInputs();
  const bt = $('#bedtime').value;
  if(!bt){ return; }
  const bedtime = new Date(bt);
  const onsetDt = new Date(bedtime.getTime() + onset*60000);
  const bestN = recommendedCycles(cycle);

  const opts = COUNTS.map(n => {
    const boundary = new Date(onsetDt.getTime() + n*cycle*60000);
    const fitbitSet = new Date(boundary.getTime() + OFFSET*60000);
    return { n, totalH:(n*cycle/60).toFixed(1), boundary, fitbitSet };
  });

  $('#results').innerHTML = '<table><thead><tr><th>Cycles</th><th>Sleep</th>'+
    '<th>Wake (ideal)</th><th>Set alarm</th></tr></thead><tbody>'+
    opts.map(o => `<tr class="${o.n===bestN?'best':''}">
      <td class="num">${o.n}${o.n===bestN?'<span class="tag">PICK</span>':''}</td>
      <td class="num">${o.totalH} h</td>
      <td class="num">${fmtTime(o.boundary)}</td>
      <td class="num set">${fmtTime(o.fitbitSet)}</td></tr>`).join('')+
    '</tbody></table>';

  $('#note').innerHTML =
    `Asleep ~${onset} min after ${fmtTime(bedtime)} (onset ${fmtTime(onsetDt)}). `+
    `<b>Set alarm</b> is 15 min past the cycle boundary so the Charge 5's Smart Wake window `+
    `(it fires within 30 min <i>before</i> the set time) brackets your light-sleep boundary. `+
    `Open Fitbit app → Alarms → enable <b>Smart Wake</b> on that time.`;
}

function recomputeReverse(){
  const { cycle, onset } = readInputs();
  const wb = $('#wakeby').value;
  if(!wb){ $('#results').innerHTML=''; $('#note').innerHTML=''; return; }
  // Resolve "up by" HH:MM to the next time it occurs.
  const [hh,mm] = wb.split(':').map(Number);
  const now = new Date();
  let wakeBy = new Date(now); wakeBy.setHours(hh, mm, 0, 0);
  if(wakeBy <= now) wakeBy.setDate(wakeBy.getDate()+1);
  // The alarm's upper bound IS wake-by; the ideal cycle boundary sits OFFSET earlier.
  const boundary = new Date(wakeBy.getTime() - OFFSET*60000);
  const bestN = recommendedCycles(cycle);

  const opts = COUNTS.map(n => {
    const onsetDt = new Date(boundary.getTime() - n*cycle*60000);
    const bedtime = new Date(onsetDt.getTime() - onset*60000);
    return { n, totalH:(n*cycle/60).toFixed(1), bedtime, onsetDt };
  });

  $('#results').innerHTML = '<table><thead><tr><th>Cycles</th><th>Sleep</th>'+
    '<th>Bed by</th><th>Asleep by</th></tr></thead><tbody>'+
    opts.map(o => `<tr class="${o.n===bestN?'best':''}">
      <td class="num">${o.n}${o.n===bestN?'<span class="tag">PICK</span>':''}</td>
      <td class="num">${o.totalH} h</td>
      <td class="num set">${fmtTime(o.bedtime)}</td>
      <td class="num">${fmtTime(o.onsetDt)}</td></tr>`).join('')+
    '</tbody></table>';

  $('#note').innerHTML =
    `You must be up by <b>${fmtTime(wakeBy)}</b> — set <i>that</i> as your Smart Wake alarm (it's the upper bound). `+
    `It fires within 30 min before, bracketing your cycle boundary at <b>${fmtTime(boundary)}</b>. `+
    `Pick a row and go to bed at the <b>Bed by</b> time to land that wake on a full cycle (asleep ~${onset} min later). `+
    `Open Fitbit app → Alarms → enable <b>Smart Wake</b> on ${fmtTime(wakeBy)}.`;
}

function setMode(m){
  mode = m;
  $('#fwdField').style.display = m === 'forward' ? '' : 'none';
  $('#revField').style.display = m === 'reverse' ? '' : 'none';
  $('#resultsHead').textContent = m === 'reverse'
    ? 'Go to bed at…' : 'Set your Fitbit Smart Wake alarm to…';
  document.querySelectorAll('#mode button').forEach(b =>
    b.classList.toggle('on', b.dataset.mode === m));
  recompute();
}

